					country: 'US',
					created_at: 1622451299,
					description:
						'Vegan food has come a long way: gone are the days of just salads. Give your tacos a healthy, vegan twist with our scruptious <a href="https://tasty.co/recipe/vegan-butternut-squash-al-pastor-tacos"Vegan Butternut Squash Tacos</a>. Chase them down with the <a href="https://tasty.co/recipe/the-best-ever-vegan-brownies"Best Ever Vegan Brownies</a>: there are no rules! Try these vegan recipes today — you won\'t regret it.',
					draft_status: 'published',
