			description:
				'Transport yourself to the sun-kissed fields of Provence with this gorgeous and flavorful ratatouille recipe. This vibrant dish captures the essence of summer with its medley of fresh vegetables and aromatic herbs. Our version features tender squash, juicy tomatoes, earthy eggplant, and sweet bell peppers, all cooked in a rich tomato sauce infused with garlic, thyme, parsley, and basil. This simple yet elegant dish is a healthy and delicious way to enjoy the best of summer produce. Whether served as a side dish or a main course, ratatouille is a delicious ode to seasonal produce and the art of French cooking.',
