					description:
						'Eating healthy does not have to be boring & mundane! These 30 salads will have you covered for a whole month. You read that right! If you\'d like to keep it simple, we have our quintessential salads like the <a href="https://tasty.co/recipe/bacon-avocado-caesar-salad">Caeser Salad</a>, <a href="https://tasty.co/recipe/grilled-veggie-steak-salad">grilled veggie and steak salad</a> and the <a href="https://tasty.co/recipe/honey-lime-fruit-salad">Honey Lime Fruit Salad</a>. But to take it up a notch, you can also go international with this <a href="https://tasty.co/recipe/asian-chicken-chopped-salad">Asian chicken chopped salad</a> or this really yummy & elaborate <a href="https://tasty.co/recipe/siga-tibs-and-ethiopian-salad">Ethiopian salad</a>. We personally love the <a href="https://tasty.co/recipe/bun-bo-xa-ot-vietnamese-steak-and-rice-noodle-salad-as-made-by-diep">Vietnamese Steak And Rice Noodle Salad</a> the most!',
