					description:
						'When you have mushroom on hand, you\'re always just minutes away from a great meal. For a delicious weeknight recipe, whip up some <a href="https://tasty.co/recipe/garlic-parmesan-stuffed-mushrooms">garlic parmesan stuffed mushroom</a> paired with a <a href="https://tasty.co/recipe/one-pot-chicken-and-mushroom-pasta">one-pot chicken mushroom pasta</a>. Or, simply whip up some comforting <a href="https://tasty.co/recipe/the-only-cream-of-mushroom-soup-recipe-youll-ever-need">cream of mushroom soup</a>! Or get a taste of Japan with this <a href="https://tasty.co/recipe/jens-japanese-arancini">Japanese arancini</a>. The options are endless!',
