					description:
						'Craving Indian food for lunch? Here\'s everything you need for a North Indian-inspired feast. You can start off with an easy-to-make <a href="https://tasty.co/recipe/easy-peasy-potato-curry">potato curry</a>, then follow it up with some delicious <a href="https://tasty.co/recipe/easy-butter-chicken">butter chicken</a>. Pair them both with an ultra-creamy <a href="https://tasty.co/recipe/indian-style-mango-lassi">mango lassi</a> — then congratulate yourself for whipping up a meal that’s probably cheaper (and tastier!) than take-out.',
