					description:
						'For sugar, spice, and everything that\'s pungent and nice, look no further than punchy ginger. The peppery-yet-sweet flavor is just to die for. We love it in our <a href="https://tasty.co/recipe/garlic-and-ginger-shrimp-stir-fry">shrimp stir fry</a> and also in a <a href="https://tasty.co/recipe/peanut-noodle-pasta-salad">Thai-inspired peanut noodle pasta salad</a>. If you\'re looking for some international recipes, try out our take on some <a href="https://tasty.co/recipe/homemade-lumpia">homemade lumpia</a> or a <a href="https://tasty.co/recipe/hainanese-chicken-rice">Hainanese chicken rice</a> – ginger is really the star. Clear your sinuses and cleanse your palate with these ginger-forward delights! ',
