					description:
						'There\'s nothing a big hearty bowl of curry can\'t fix! Grab your favorite bread and get ready for some delicious curries. For a quick and tasty meal, check out <a href="https://tasty.co/recipe/simple-veggie-curry">Simple Veggie Curry</a>! <a href="https://tasty.co/recipe/chicken-curry-naan-bowls">Chicken Curry Naan Bowls</a> are the best thing you could have for dinner! Potato lovers, you must try the <a href="https://tasty.co/recipe/easy-peasy-potato-curry">Easy-Peasy Potato Curry</a>!',
